import os

from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class TRSv2HttpClient(HttpClient):
    """ This class provides a client for the TRS v2 API. """

    def __init__(self, base_url, connection_alias):
        super(TRSv2HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/trs/v2"

    def get_csr_file(self, key_pool_type, timeout):
        endpoint = "/operator/csr"
        headers = {
            "accept": "*/*",
        }
        params = {
            "keyPoolType": key_pool_type,
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, payload=params, timeout=timeout)

    def generate_csr_for_ne(self, key_pool_type):
        endpoint = "/operator/csr"
        headers = {
            "accept": "application/json",
        }
        json_data = {
            "keyPoolType": key_pool_type,
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, json=json_data)

    def install_operators_certificate(self, certificate_file_path, certificate_type):
        endpoint = "/operator/certificates"
        headers = {
            "Content-Type": "application/json",
            "accept": "application/json",
        }

        with open(certificate_file_path, 'r+') as certificate_file:
            file_content = certificate_file.read()

        file_path, file_extension = os.path.splitext(certificate_file_path)
        file_encoding = file_extension.split('.')[-1]
        file_name = file_path.split('/')[-1]

        files = {
            'certificateFile': file_content,
            'certificateType': certificate_type,
            'fileEncoding': file_encoding,
            'fileName': file_name
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, json=files)

    def get_operator_certificate_list(self, timeout):
        endpoint = "/operator/certificates"
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def delete_all_operator_certificates(self):
        endpoint = "/operator/certificates"
        headers = {
            "accept": "application/json",
        }

        return self._send_delete_request(endpoint=endpoint, headers=headers)

    def get_operator_certificate(self, certificate_id, timeout):
        endpoint = f"/operator/certificates/{certificate_id}"
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def delete_operator_certificate(self, certificate_id):
        endpoint = f"/operator/certificates/{certificate_id}"
        headers = {
            "accept": "application/json",
        }

        return self._send_delete_request(endpoint=endpoint, headers=headers)

    def trigger_certificate_initialization(self, key_pool_type):
        endpoint = "/cmp/certificate-initialization"
        headers = {
            "Content-Type": "application/json",
            "accept": "application/json",
        }
        json_data = {
            "keyPoolType": key_pool_type,
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, json=json_data)

    def trigger_cmp_server_key_update(self, key_pool_type):
        endpoint = "/cmp/server/key"
        headers = {
            "Content-Type": "application/json",
            "accept": "application/json",
        }
        json_data = {
            "keyPoolType": key_pool_type,
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, json=json_data)

    def update_cmp_server_settings(self, ref_number, psk_key, key_pool_type):
        endpoint = "/cmp/server/settings"
        headers = {
            "Content-Type": "application/json",
            "accept": "application/json",
        }
        json_data = {
            "refNumber": ref_number,
            "pskKey": psk_key,
            "keyPoolType": key_pool_type,
        }

        return self._send_put_request(endpoint=endpoint, headers=headers, json=json_data)

    def trigger_crl_information_update(self):
        endpoint = "/crl"
        headers = {
            "Content-Type": "application/json",
            "accept": "application/json",
        }

        return self._send_post_request(endpoint=endpoint, headers=headers)

    def get_current_crl(self, timeout):
        endpoint = "/crl"
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)
